contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 supply, uint256 burnAmount) public {
        vm.assume(supply > 0 && supply <= type(uint256).max / 2);
        vm.assume(burnAmount > 0 && burnAmount <= supply);
        c = new ERCDDAToken(supply, "Token", "TKN");
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 ownerBalanceBefore = c.balanceOf(address(this));
        vm.prank(address(this));
        bool ok;
        try c.burn(burnAmount) returns (bool res) { ok = res; } catch { ok = false; }
        if (ok) {
            uint256 totalBalance = c.balanceOf(address(this));
            assertTrue(totalBalance == c.totalSupply());
        }
    }
}
